WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_age_x_complex'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '复杂年龄关系', 'kp-age-x-complex', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "复杂年龄推理"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "这已经不是数学题了，是剧本杀推理题。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、破题法"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“甲比乙大，丙不是最大的，乙的年龄是甲丙之和的一半……”"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "遇到这种逻辑推理混合年龄，第一步必须排出一个【大小序列】。比如 甲 > 乙 > 丙。有了序列，谁是谁的倍数、谁和谁的差才能对应到具体的等式上。否则很容易把被减数搞反。"}]}]}$$ AS jsonb), NULL, '复杂年龄关系的核心考点与实战推导。', category_node.id, CAST('["数量关系", "年龄问题", "复杂年龄关系"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_age_x_complex", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
